import csv
import json
import os
from pyscipopt import Model, quicksum

DATA = "/app/data"
OUT = "/app/submissions"

os.makedirs(OUT, exist_ok=True)

# ---- Load data ----
with open(os.path.join(DATA, "config.json")) as f:
    cfg = json.load(f)
durable_threshold = cfg["durable_year_threshold"]
tol = cfg.get("feasibility_tolerance", 1e-5)

buyers = {}
with open(os.path.join(DATA, "buyers.csv")) as f:
    for row in csv.DictReader(f):
        b = row["buyer_id"]
        buyers[b] = {
            "home_region": row["home_region"],
            "target": float(row["target_tonnes"]),
            "budget_kusd": float(row["budget_kusd"]),
            "min_durable_share": float(row["min_durable_share"]),
            "min_home_region_share": float(row["min_home_region_share"]),
            "max_single_project_share": float(row["max_single_project_share"]),
        }

projects = {}
with open(os.path.join(DATA, "projects.csv")) as f:
    for row in csv.DictReader(f):
        p = row["project_id"]
        projects[p] = {
            "region": row["region"],
            "permanence": float(row["permanence_years"]),
            "available": float(row["available_tonnes"]),
            "price": float(row["price_per_tonne"]),
            "fixed": float(row["fixed_onboarding_kusd"]),
            "min_contract": float(row["min_contract_tonnes"]),
        }

elig = {}
with open(os.path.join(DATA, "buyer_project_eligibility.csv")) as f:
    for row in csv.DictReader(f):
        b, p = row["buyer_id"], row["project_id"]
        elig[(b, p)] = {
            "max": float(row["max_tonnes"]),
            "bonus": float(row["preference_bonus_per_tonne"]),
        }

# ---- Build model ----
model = Model("carbon_removal_credit_portfolio")
model.setParam("gaprel", 0.0005)

time_limit = 300.0
env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
if env_limit is not None:
    try:
        time_limit = min(time_limit, float(env_limit))
    except ValueError:
        pass
model.setParam("limits/time", time_limit)

y = {}
for p in projects:
    y[p] = model.addVar(name=f"y_{p}", vtype="B", lb=0.0, ub=1.0, obj=0.0)

x = {}
obj_coeff = {}
for (b, p), e in elig.items():
    v = model.addVar(name=f"x_{b}_{p}", vtype="C", lb=0.0, ub=e["max"], obj=0.0)
    x[(b, p)] = v
    obj_coeff[(b, p)] = projects[p]["price"] - e["bonus"]

# Objective
obj_expr = quicksum([projects[p]["fixed"] * y[p] for p in projects])
obj_expr += quicksum([obj_coeff[k] * x[k] for k in x])
model.setObjective(obj_expr, sense="minimize")

# Linking: x <= max * y
for (b, p), e in elig.items():
    model.addCons(x[(b, p)] <= e["max"] * y[p], name=f"link_{b}_{p}")

# Project min contract and capacity
for p in projects:
    pairs = [(b, p) for (b, q) in elig if q == p]
    if not pairs:
        # project cannot be contracted usefully; force y=0
        model.chgVarUb(y[p], 0.0)
        continue
    s = quicksum([x[k] for k in pairs])
    model.addCons(s >= projects[p]["min_contract"] * y[p], name=f"mincontract_{p}")
    model.addCons(s <= projects[p]["available"], name=f"capacity_{p}")

# Buyer constraints
for b, bd in buyers.items():
    pairs = [(b, p) for (q, p) in elig if q == b]
    s = quicksum([x[k] for k in pairs])
    # target
    model.addCons(s == bd["target"], name=f"target_{b}")
    # budget (unadjusted price)
    model.addCons(
        quicksum([projects[p]["price"] * x[(b, p)] for (b2, p) in pairs])
        <= bd["budget_kusd"] * 1000.0,
        name=f"budget_{b}",
    )
    # durable floor
    dur = [k for k in pairs if projects[k[1]]["permanence"] >= durable_threshold]
    if dur:
        model.addCons(
            quicksum([x[k] for k in dur]) >= bd["min_durable_share"] * bd["target"],
            name=f"durable_{b}",
        )
    else:
        model.chgVarUb(y[p], 0.0) if False else None
        # infeasible buyer; leave to solver to detect
    # home region floor
    home = [k for k in pairs if projects[k[1]]["region"] == bd["home_region"]]
    if home:
        model.addCons(
            quicksum([x[k] for k in home]) >= bd["min_home_region_share"] * bd["target"],
            name=f"home_{b}",
        )
    # concentration cap
    for k in pairs:
        model.addCons(
            x[k] <= bd["max_single_project_share"] * bd["target"],
            name=f"conc_{b}_{k[1]}",
        )

# ---- Solve ----
status = "unknown"
objval = None
try:
    model.optimize()
    status = model.getStatus()
    if model.getNSols() > 0:
        objval = model.getObjVal()
except Exception as e:
    print(f"Solver error: {e}")

# ---- Extract solution ----
sol_path = os.path.join(OUT, "solution.csv")
rows = []
try:
    if model.getNSols() > 0:
        for p in projects:
            if model.getVal(y[p]) > 0.5:
                rows.append(["contract", "", p, "1"])
        for k, v in x.items():
            val = model.getVal(v)
            if val > 1e-8:
                b, p = k
                rows.append(["allocate", b, p, f"{val:.8f}"])
except Exception as e:
    print(f"Extraction error: {e}")

with open(sol_path, "w", newline="") as f:
    w = csv.writer(f)
    w.writerow(["row_type", "buyer_id", "project_id", "value"])
    for r in rows:
        w.writerow(r)

# ---- Validation ----
print(f"Status: {status}")
print(f"Objective: {objval}")
alloc = {}
contracted = set()
for p in projects:
    try:
        if model.getVal(y[p]) > 0.5:
            contracted.add(p)
    except Exception:
        pass
for k, v in x.items():
    try:
        val = model.getVal(v)
    except Exception:
        val = 0.0
    alloc[k] = val

ok = True
for b, bd in buyers.items():
    tot = sum(alloc.get((b, p), 0.0) for (q, p) in elig if q == b)
    if abs(tot - bd["target"]) > tol:
        ok = False
        print(f"FAIL target {b}: {tot} vs {bd['target']}")
    cost = sum(projects[p]["price"] * alloc.get((b, p), 0.0) for (q, p) in elig if q == b)
    if cost > bd["budget_kusd"] * 1000.0 + tol:
        ok = False
        print(f"FAIL budget {b}: {cost}")
    dur = sum(
        alloc.get((b, p), 0.0)
        for (q, p) in elig
        if q == b and projects[p]["permanence"] >= durable_threshold
    )
    if dur < bd["min_durable_share"] * bd["target"] - tol:
        ok = False
        print(f"FAIL durable {b}: {dur}")
    home = sum(
        alloc.get((b, p), 0.0)
        for (q, p) in elig
        if q == b and projects[p]["region"] == bd["home_region"]
    )
    if home < bd["min_home_region_share"] * bd["target"] - tol:
        ok = False
        print(f"FAIL home {b}: {home}")
    for (q, p) in elig:
        if q == b:
            if alloc.get((b, p), 0.0) > bd["max_single_project_share"] * bd["target"] + tol:
                ok = False
                print(f"FAIL conc {b} {p}")
            if alloc.get((b, p), 0.0) > elig[(b, p)]["max"] + tol:
                ok = False
                print(f"FAIL maxpair {b} {p}")
            if p not in contracted and alloc.get((b, p), 0.0) > tol:
                ok = False
                print(f"FAIL uncontracted {b} {p}")
for p in projects:
    tot = sum(alloc.get((b, p), 0.0) for (b, q) in elig if q == p)
    if p in contracted:
        if tot < projects[p]["min_contract"] - tol:
            ok = False
            print(f"FAIL mincontract {p}: {tot}")
    if tot > projects[p]["available"] + tol:
        ok = False
        print(f"FAIL capacity {p}: {tot}")

print("Validation:", "PASS" if ok else "FAIL")

try:
    model.free()
except Exception:
    pass
